insert into prix_ingredients (foyer_id, nom, prix, quantite, unite, produit, estime)
select f.id, v.* from (select id from foyers order by cree_le limit 1) f, (values
('Bœuf à mijoter',9.76,620,'g','Bœuf bourguignon à mijoter Atelier de Gustave 620 g',false),
('Hauts de cuisse de poulet',3.39,700,'g','Hauts de cuisses de poulet Petit Prix 700 g',false),
('Feuilles de lasagne',2.09,250,'g','Feuilles de lasagnes fraîches Carrefour Classic'' 250 g',false),
('Semoule complète',1.95,500,'g','Couscous semi-complet Carrefour Bio 500 g',false),
('Petits pois',1.79,1000,'g','Petits pois très fins Carrefour Classic'' 1 kg (surgelé)',false),
('Sauté de porc',5.14,530,'g','Sauté de porc sans os Atelier de Gustave 530 g',false),
('Aubergine',1.49,1,'pièce','Aubergine à la pièce',false),
('Saucisses de volaille',1.69,10,'pièce','Knacki 100 % poulet Herta x10',false),
('Pains burger',0.99,6,'pièce','Pains burger Carrefour Classic'' x6',false),
('Chou-fleur',1.35,2,'pièce','Chou-fleur en fleurettes Simpl 1 kg (surgelé)',false)
) v(nom, prix, quantite, unite, produit, estime)
on conflict (foyer_id, nom) do update set prix = excluded.prix, quantite = excluded.quantite, unite = excluded.unite, produit = excluded.produit, estime = excluded.estime, maj = current_date;
with data as (select $j$[{"n":"Curry de poulet aux légumes et riz","p":4,"t":35,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de poulet",600,"g"],["Lait de coco",1,"boîte"],["Courgettes",2,"pièce"],["Poivrons",2,"pièce"],["Oignon",1,"pièce"],["Riz basmati",300,"g"],["Curry"]],"e":"Faire revenir l'oignon et le poulet en dés avec le curry 5 min.\nAjouter les légumes en dés et le lait de coco, mijoter 15 min.\nCuire le riz et répartir en 4 boîtes avec le curry.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Bœuf mijoté aux carottes et pommes de terre","p":4,"t":120,"g":["viande","gamelle","healthy"],"i":[["Bœuf à mijoter",620,"g"],["Carottes",6,"pièce"],["Oignon",2,"pièce"],["Champignons",250,"g"],["Pommes de terre",6,"pièce"],["Bouillon cube",1,"pièce"],["Thym"]],"e":"Dorer le bœuf en morceaux dans une cocotte, ajouter les oignons.\nCouvrir de bouillon, ajouter les carottes et le thym, mijoter 1 h 30 à couvert.\nAjouter les pommes de terre et les champignons pour les 30 dernières minutes.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Hachis parmentier de patate douce","p":4,"t":50,"g":["viande","gamelle","healthy"],"i":[["Viande hachée 5 %",500,"g"],["Patates douces",4,"pièce"],["Oignon",1,"pièce"],["Concentré de tomates",1,"boîte"],["Emmental râpé",60,"g"]],"e":"Cuire les patates douces 20 min à l'eau, les écraser en purée.\nFaire revenir l'oignon et la viande avec le concentré de tomates.\nÉtaler la viande puis la purée dans un plat, parsemer d'emmental.\nGratiner 20 min à 200 °C, puis découper en 4 parts.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Lasagnes légères à la bolognaise","p":4,"t":60,"g":["viande","gamelle","healthy"],"i":[["Viande hachée 5 %",500,"g"],["Feuilles de lasagne",250,"g"],["Tomates concassées",2,"boîte"],["Courgettes",2,"pièce"],["Lait demi-écrémé",500,"mL"],["Emmental râpé",80,"g"],["Oignon",1,"pièce"]],"e":"Préparer la bolognaise : oignon, viande, courgettes râpées et tomates, 15 min.\nÉpaissir le lait chaud avec 2 c. à s. de maïzena pour une béchamel légère.\nAlterner feuilles, bolognaise et béchamel, finir par l'emmental.\nCuire 35 min à 180 °C.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Sauté de dinde aux poivrons et boulgour","p":4,"t":35,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de dinde",600,"g"],["Poivrons",3,"pièce"],["Tomates concassées",1,"boîte"],["Oignon",1,"pièce"],["Boulgour",300,"g"],["Paprika"]],"e":"Saisir la dinde en lanières avec le paprika.\nAjouter l'oignon et les poivrons, puis les tomates, mijoter 15 min.\nCuire le boulgour et répartir.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Colombo de poulet et riz","p":4,"t":50,"g":["volaille","gamelle","healthy"],"i":[["Hauts de cuisse de poulet",700,"g"],["Pommes de terre",4,"pièce"],["Courgettes",2,"pièce"],["Lait de coco",0.5,"boîte"],["Oignon",1,"pièce"],["Riz basmati",300,"g"],["Épices colombo"]],"e":"Dorer le poulet avec l'oignon et les épices.\nAjouter les pommes de terre et les courgettes en cubes, le lait de coco et un verre d'eau.\nMijoter 35 min à couvert.\nServir avec le riz.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Boulettes de poulet sauce tomate et pâtes complètes","p":4,"t":40,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de poulet",500,"g"],["Œufs",1,"pièce"],["Tomates concassées",2,"boîte"],["Pâtes complètes",320,"g"],["Oignon",1,"pièce"],["Herbes de Provence"]],"e":"Mixer le poulet avec l'œuf et les herbes, former des boulettes.\nLes dorer, ajouter l'oignon et les tomates, mijoter 20 min.\nCuire les pâtes et répartir.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Gratin de pâtes au thon et brocoli","p":4,"t":40,"g":["poisson","gamelle","healthy"],"i":[["Pâtes complètes",320,"g"],["Thon au naturel",3,"boîte"],["Brocoli",2,"pièce"],["Crème légère",200,"mL"],["Emmental râpé",80,"g"]],"e":"Cuire les pâtes et le brocoli ensemble 8 min.\nMélanger avec le thon émietté et la crème.\nParsemer d'emmental et gratiner 20 min à 200 °C.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Brandade légère de colin","p":4,"t":45,"g":["poisson","gamelle","healthy"],"i":[["Filets de colin",500,"g"],["Pommes de terre",8,"pièce"],["Lait demi-écrémé",200,"mL"],["Ail"],["Persil"]],"e":"Cuire les pommes de terre 20 min, le colin 8 min dans le lait frémissant.\nÉcraser les pommes de terre avec le lait, l'ail et le poisson émietté.\nMettre en plat, gratiner 15 min à 200 °C.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Couscous de poulet aux légumes","p":4,"t":50,"g":["volaille","gamelle","healthy"],"i":[["Hauts de cuisse de poulet",700,"g"],["Semoule complète",300,"g"],["Carottes",4,"pièce"],["Courgettes",2,"pièce"],["Pois chiches",1,"boîte"],["Oignon",1,"pièce"],["Tomates concassées",1,"boîte"],["Ras el hanout"]],"e":"Dorer le poulet avec l'oignon et les épices.\nAjouter carottes, tomates et 1 L d'eau, mijoter 25 min.\nAjouter courgettes et pois chiches, 15 min.\nPréparer la semoule et répartir.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Tajine de poulet, carottes et pois chiches","p":4,"t":55,"g":["volaille","gamelle","healthy"],"i":[["Hauts de cuisse de poulet",700,"g"],["Carottes",4,"pièce"],["Pois chiches",1,"boîte"],["Oignon",2,"pièce"],["Citron",1,"pièce"],["Semoule complète",300,"g"],["Cumin"]],"e":"Dorer le poulet, ajouter les oignons émincés et le cumin.\nAjouter les carottes, le jus du citron et 30 cl d'eau, mijoter 35 min.\nAjouter les pois chiches 10 min.\nServir avec la semoule.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Blanquette de dinde et riz","p":4,"t":45,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de dinde",600,"g"],["Carottes",4,"pièce"],["Champignons",250,"g"],["Crème légère",200,"mL"],["Bouillon cube",1,"pièce"],["Riz basmati",300,"g"]],"e":"Faire revenir la dinde en cubes.\nCouvrir de bouillon, ajouter les carottes, cuire 20 min.\nAjouter les champignons 10 min, puis la crème.\nServir avec le riz.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Chili con carne à congeler","p":4,"t":50,"g":["viande","gamelle","healthy"],"i":[["Viande hachée 5 %",600,"g"],["Haricots rouges",2,"boîte"],["Tomates concassées",2,"boîte"],["Maïs doux",1,"boîte"],["Poivrons",2,"pièce"],["Oignon",2,"pièce"],["Riz basmati",300,"g"],["Cumin"],["Paprika"]],"e":"Faire revenir les oignons, les poivrons et la viande.\nAjouter épices, tomates, haricots et maïs, mijoter 30 min.\nCuire le riz et répartir.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Riz cantonais au poulet","p":4,"t":30,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de poulet",400,"g"],["Riz basmati",300,"g"],["Œufs",3,"pièce"],["Petits pois",300,"g"],["Carottes",2,"pièce"],["Oignon",1,"pièce"],["Sauce soja"]],"e":"Cuire le riz la veille ou le laisser refroidir.\nFaire une omelette fine, la couper en lanières.\nSauter le poulet en dés, l'oignon, les carottes et les petits pois.\nAjouter le riz et la sauce soja, puis l'omelette.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Poulet tikka masala et riz","p":4,"t":40,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de poulet",600,"g"],["Yaourt grec",2,"pot"],["Tomates concassées",1,"boîte"],["Crème légère",100,"mL"],["Oignon",1,"pièce"],["Riz basmati",300,"g"],["Garam masala"]],"e":"Mariner le poulet en dés dans le yaourt et les épices.\nFaire revenir l'oignon, ajouter le poulet, puis les tomates, 15 min.\nAjouter la crème, servir avec le riz.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Keftas de bœuf, semoule et courgettes","p":4,"t":40,"g":["viande","gamelle","healthy"],"i":[["Viande hachée 5 %",500,"g"],["Semoule complète",300,"g"],["Courgettes",3,"pièce"],["Yaourt grec",2,"pot"],["Oignon",1,"pièce"],["Cumin"]],"e":"Mélanger la viande, l'oignon haché et le cumin, former des keftas.\nLes cuire 10 min à la poêle.\nPoêler les courgettes en rondelles, préparer la semoule.\nServir avec le yaourt en sauce (à part dans la boîte).\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Sauté de porc aux champignons et riz","p":4,"t":50,"g":["viande","gamelle","healthy"],"i":[["Sauté de porc",530,"g"],["Champignons",400,"g"],["Crème légère",200,"mL"],["Oignon",1,"pièce"],["Riz basmati",300,"g"],["Moutarde"]],"e":"Dorer le porc en morceaux avec l'oignon.\nAjouter un verre d'eau et mijoter 30 min à couvert.\nAjouter les champignons 10 min, puis la crème et une cuillère de moutarde.\nServir avec le riz.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Ratatouille au poulet et quinoa","p":4,"t":50,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de poulet",500,"g"],["Courgettes",2,"pièce"],["Aubergine",1,"pièce"],["Poivrons",2,"pièce"],["Tomates concassées",1,"boîte"],["Quinoa",300,"g"],["Oignon",1,"pièce"],["Herbes de Provence"]],"e":"Faire revenir les légumes en dés 10 min, ajouter les tomates et mijoter 25 min.\nSaisir le poulet en dés et l'ajouter.\nCuire le quinoa et répartir.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Curry de colin au lait de coco et riz","p":4,"t":35,"g":["poisson","gamelle","healthy"],"i":[["Filets de colin",600,"g"],["Lait de coco",1,"boîte"],["Tomates concassées",1,"boîte"],["Épinards frais",200,"g"],["Riz basmati",300,"g"],["Oignon",1,"pièce"],["Curry"]],"e":"Faire revenir l'oignon avec le curry.\nAjouter tomates et lait de coco, mijoter 10 min.\nAjouter le colin en morceaux et les épinards, 8 min.\nServir avec le riz.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Saucisses de volaille aux lentilles","p":4,"t":45,"g":["volaille","gamelle","healthy"],"i":[["Saucisses de volaille",6,"pièce"],["Lentilles vertes",400,"g"],["Carottes",3,"pièce"],["Oignon",1,"pièce"],["Bouillon cube",1,"pièce"],["Thym"]],"e":"Faire revenir l'oignon et les carottes en dés.\nAjouter les lentilles, le bouillon et 3 fois leur volume d'eau, cuire 25 min.\nAjouter les saucisses coupées 5 min avant la fin.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Bolognaise allégée bœuf et lentilles","p":4,"t":40,"g":["viande","gamelle","healthy"],"i":[["Viande hachée 5 %",400,"g"],["Lentilles corail",150,"g"],["Tomates concassées",2,"boîte"],["Carottes",2,"pièce"],["Oignon",1,"pièce"],["Pâtes complètes",320,"g"]],"e":"Faire revenir l'oignon, les carottes râpées et la viande.\nAjouter les lentilles, les tomates et 30 cl d'eau, mijoter 20 min.\nCuire les pâtes et répartir.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Curry de poulet aux pois chiches et épinards","p":4,"t":35,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de poulet",500,"g"],["Pois chiches",1,"boîte"],["Épinards frais",300,"g"],["Lait de coco",1,"boîte"],["Riz basmati",300,"g"],["Oignon",1,"pièce"],["Curry"]],"e":"Faire revenir l'oignon et le poulet avec le curry.\nAjouter le lait de coco et les pois chiches, mijoter 12 min.\nAjouter les épinards jusqu'à ce qu'ils fondent.\nServir avec le riz.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Paëlla légère poulet et crevettes","p":4,"t":45,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de poulet",400,"g"],["Crevettes décortiquées",200,"g"],["Riz basmati",300,"g"],["Poivrons",2,"pièce"],["Petits pois",200,"g"],["Tomates concassées",1,"boîte"],["Oignon",1,"pièce"],["Curcuma"]],"e":"Dorer le poulet en dés avec l'oignon et les poivrons.\nAjouter le riz, le curcuma, les tomates et 75 cl d'eau, cuire 18 min.\nAjouter les petits pois et les crevettes 5 min avant la fin.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Gratin de courgettes au poulet et riz","p":4,"t":45,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de poulet",400,"g"],["Courgettes",4,"pièce"],["Riz basmati",200,"g"],["Crème légère",200,"mL"],["Emmental râpé",80,"g"]],"e":"Cuire le riz. Poêler le poulet en dés et les courgettes en rondelles.\nMélanger avec le riz et la crème dans un plat, parsemer d'emmental.\nGratiner 20 min à 200 °C.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Soupe-repas au poulet, légumes et pâtes","p":4,"t":40,"g":["volaille","gamelle","healthy"],"i":[["Escalopes de poulet",400,"g"],["Carottes",3,"pièce"],["Poireaux",2,"pièce"],["Pâtes complètes",150,"g"],["Bouillon cube",2,"pièce"]],"e":"Faire revenir les poireaux et les carottes en rondelles.\nAjouter 1,5 L d'eau et le bouillon, cuire 15 min.\nAjouter le poulet en dés et les pâtes, cuire 10 min.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Quiche sans pâte au thon et courgettes","p":4,"t":45,"g":["poisson","gamelle","healthy"],"i":[["Thon au naturel",2,"boîte"],["Œufs",5,"pièce"],["Courgettes",2,"pièce"],["Lait demi-écrémé",250,"mL"],["Emmental râpé",60,"g"]],"e":"Poêler les courgettes râpées 5 min pour les sécher.\nBattre les œufs et le lait, ajouter le thon, les courgettes et l'emmental.\nCuire 35 min à 180 °C dans un moule, découper en 4 parts.\nÀ conserver 3 jours au frigo en boîtes, ou jusqu'à 3 mois au congélateur. Réchauffer 2 à 3 min au micro-ondes en remuant à mi-chemin."},{"n":"Poulet au paprika, poivrons et semoule","p":2,"t":25,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Poivrons",2,"pièce"],["Semoule complète",150,"g"],["Yaourt grec",1,"pot"],["Paprika"]],"e":"Saisir le poulet en lanières avec le paprika.\nAjouter les poivrons émincés, cuire 8 min.\nPréparer la semoule, servir avec le yaourt."},{"n":"Dinde au curry, haricots verts et riz","p":2,"t":25,"g":["volaille","healthy"],"i":[["Escalopes de dinde",300,"g"],["Haricots verts",300,"g"],["Riz basmati",150,"g"],["Crème légère",100,"mL"],["Curry"]],"e":"Cuire le riz et les haricots verts.\nSaisir la dinde en dés avec le curry, ajouter la crème."},{"n":"Saumon sauce yaourt-concombre et pommes de terre","p":2,"t":30,"g":["poisson","healthy"],"i":[["Pavés de saumon",2,"pièce"],["Pommes de terre",4,"pièce"],["Yaourt grec",1,"pot"],["Concombre",1,"pièce"],["Aneth"]],"e":"Cuire les pommes de terre à la vapeur 20 min.\nCuire le saumon 4 min par face.\nMélanger yaourt, concombre râpé et aneth pour la sauce."},{"n":"Saumon teriyaki, nouilles et légumes","p":2,"t":25,"g":["poisson","healthy"],"i":[["Pavés de saumon",2,"pièce"],["Nouilles de riz",150,"g"],["Carottes",2,"pièce"],["Courgette",1,"pièce"],["Sauce soja"],["Miel"]],"e":"Réhydrater les nouilles.\nSaisir le saumon, ajouter sauce soja et miel pour laquer.\nSauter les légumes en julienne, ajouter les nouilles."},{"n":"Cabillaud rôti, purée de patate douce et épinards","p":2,"t":30,"g":["poisson","healthy"],"i":[["Filets de cabillaud",300,"g"],["Patates douces",2,"pièce"],["Épinards frais",150,"g"]],"e":"Cuire les patates douces 20 min, écraser en purée.\nRôtir le cabillaud 12 min à 200 °C.\nFaire tomber les épinards à la poêle."},{"n":"Colin pané au four et haricots verts","p":2,"t":25,"g":["poisson","healthy"],"i":[["Filets de colin",300,"g"],["Œufs",1,"pièce"],["Haricots verts",300,"g"],["Chapelure"]],"e":"Passer le colin dans l'œuf battu puis la chapelure, cuire 15 min à 200 °C.\nCuire les haricots verts 8 min."},{"n":"Crevettes sautées au brocoli et riz","p":2,"t":20,"g":["poisson","healthy","rapide"],"i":[["Crevettes décortiquées",250,"g"],["Brocoli",1,"pièce"],["Riz basmati",150,"g"],["Sauce soja"],["Ail"]],"e":"Cuire le riz et le brocoli 5 min à la vapeur.\nSauter les crevettes avec l'ail 3 min, ajouter le brocoli et la sauce soja."},{"n":"Steak haché et purée de brocoli maison","p":2,"t":25,"g":["viande","healthy"],"i":[["Steaks hachés 5 %",2,"pièce"],["Brocoli",1,"pièce"],["Pommes de terre",2,"pièce"]],"e":"Cuire brocoli et pommes de terre 20 min, mixer en purée.\nCuire les steaks à la poêle."},{"n":"Burger maison léger et frites de patate douce","p":2,"t":35,"g":["viande","healthy"],"i":[["Steaks hachés 5 %",2,"pièce"],["Pains burger",2,"pièce"],["Tomates",1,"pièce"],["Salade verte",1,"pièce"],["Oignon rouge",1,"pièce"],["Patates douces",2,"pièce"]],"e":"Couper les patates douces en frites, les cuire 25 min à 200 °C.\nCuire les steaks, garnir les pains de salade, tomate et oignon."},{"n":"Fajitas de bœuf aux poivrons","p":2,"t":25,"g":["viande","healthy"],"i":[["Émincé de bœuf",300,"g"],["Poivrons",2,"pièce"],["Oignon",1,"pièce"],["Tortillas complètes",4,"pièce"],["Mélange épices fajitas",1,"sachet"],["Yaourt grec",1,"pot"]],"e":"Saisir le bœuf 2 min à feu vif, réserver.\nSauter poivrons et oignon avec les épices 6 min, remettre le bœuf.\nGarnir les tortillas, servir avec le yaourt."},{"n":"Poulet grillé, salade de quinoa, concombre et feta","p":2,"t":25,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Quinoa",150,"g"],["Concombre",1,"pièce"],["Tomates cerises",150,"g"],["Feta",100,"g"]],"e":"Cuire le quinoa et le laisser tiédir.\nGriller le poulet.\nMélanger quinoa, concombre, tomates et feta, servir avec le poulet."},{"n":"Escalopes de dinde aux champignons et pâtes complètes","p":2,"t":25,"g":["volaille","healthy"],"i":[["Escalopes de dinde",300,"g"],["Champignons",250,"g"],["Crème légère",100,"mL"],["Pâtes complètes",160,"g"]],"e":"Cuire les pâtes.\nSaisir la dinde, réserver ; faire revenir les champignons 6 min.\nAjouter la crème et la dinde, 2 min."},{"n":"Saumon, lentilles vertes et carottes","p":2,"t":35,"g":["poisson","healthy"],"i":[["Pavés de saumon",2,"pièce"],["Lentilles vertes",150,"g"],["Carottes",2,"pièce"],["Échalote",1,"pièce"]],"e":"Cuire les lentilles 20 min avec les carottes en dés.\nCuire le saumon 4 min par face.\nAssaisonner les lentilles avec l'échalote ciselée."},{"n":"Frittata au poulet et épinards","p":2,"t":20,"g":["volaille","healthy","rapide"],"i":[["Œufs",5,"pièce"],["Blanc de poulet",4,"tranche"],["Épinards frais",150,"g"],["Emmental râpé",40,"g"],["Salade verte",1,"pièce"]],"e":"Faire tomber les épinards dans une poêle.\nAjouter le poulet en lanières et les œufs battus avec l'emmental.\nCuire 10 min à feu doux à couvert. Servir avec la salade."},{"n":"Wok de bœuf au brocoli","p":2,"t":20,"g":["viande","healthy","rapide"],"i":[["Émincé de bœuf",300,"g"],["Brocoli",1,"pièce"],["Riz basmati",150,"g"],["Sauce soja"],["Gingembre"]],"e":"Cuire le riz.\nSaisir le bœuf 2 min, réserver.\nSauter le brocoli 5 min, remettre le bœuf avec la sauce soja et le gingembre."},{"n":"Crevettes à la provençale et riz","p":2,"t":25,"g":["poisson","healthy"],"i":[["Crevettes décortiquées",250,"g"],["Tomates concassées",1,"boîte"],["Courgette",1,"pièce"],["Riz basmati",150,"g"],["Ail"],["Herbes de Provence"]],"e":"Cuire le riz.\nFaire revenir la courgette en dés avec l'ail, ajouter les tomates, 10 min.\nAjouter les crevettes 4 min."},{"n":"Cuisses de poulet aux herbes, haricots verts et pommes de terre","p":2,"t":50,"g":["volaille","healthy"],"i":[["Cuisses de poulet",2,"pièce"],["Haricots verts",300,"g"],["Pommes de terre",3,"pièce"],["Herbes de Provence"]],"e":"Rôtir les cuisses et les pommes de terre en quartiers 45 min à 200 °C.\nCuire les haricots verts 8 min."},{"n":"Lieu noir au four et ratatouille express","p":2,"t":35,"g":["poisson","healthy"],"i":[["Filets de lieu noir",300,"g"],["Courgette",1,"pièce"],["Aubergine",1,"pièce"],["Poivron",1,"pièce"],["Tomates",2,"pièce"]],"e":"Faire revenir les légumes en dés 20 min.\nCuire le poisson 12 min à 200 °C sur les légumes."},{"n":"Brochettes de poulet, sauce yaourt et boulgour","p":2,"t":30,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Boulgour",150,"g"],["Yaourt grec",1,"pot"],["Courgette",1,"pièce"],["Oignon rouge",1,"pièce"]],"e":"Monter les brochettes poulet, courgette et oignon.\nLes griller 12 min.\nCuire le boulgour, servir avec le yaourt assaisonné."},{"n":"Salade tiède de saumon, pommes de terre et haricots verts","p":2,"t":30,"g":["poisson","healthy"],"i":[["Pavés de saumon",2,"pièce"],["Pommes de terre",3,"pièce"],["Haricots verts",200,"g"],["Salade verte",1,"pièce"],["Moutarde"]],"e":"Cuire pommes de terre et haricots verts.\nCuire le saumon et l'émietter.\nAssembler sur la salade avec une vinaigrette à la moutarde."},{"n":"Bowl de bœuf à la coréenne","p":2,"t":25,"g":["viande","healthy"],"i":[["Viande hachée 5 %",300,"g"],["Riz basmati",150,"g"],["Carottes",2,"pièce"],["Concombre",1,"pièce"],["Œufs",2,"pièce"],["Sauce soja"],["Gingembre"]],"e":"Cuire le riz.\nSaisir la viande avec la sauce soja et le gingembre.\nCuire les œufs au plat.\nDresser avec carottes râpées et concombre."},{"n":"Poulet milanaise au four et spaghetti complets","p":2,"t":30,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Œufs",1,"pièce"],["Pâtes complètes",160,"g"],["Tomates concassées",1,"boîte"],["Chapelure"]],"e":"Paner le poulet (œuf, chapelure), cuire 18 min à 200 °C.\nCuire les pâtes, réchauffer les tomates assaisonnées."},{"n":"Papillote de cabillaud aux petits légumes et quinoa","p":2,"t":30,"g":["poisson","healthy"],"i":[["Filets de cabillaud",300,"g"],["Courgette",1,"pièce"],["Carottes",2,"pièce"],["Quinoa",150,"g"],["Citron",1,"pièce"]],"e":"Cuire le quinoa.\nFermer en papillote cabillaud, légumes en julienne et citron, cuire 15 min à 200 °C."},{"n":"Poulet au curry et chou-fleur rôti","p":2,"t":35,"g":["volaille","healthy"],"i":[["Escalopes de poulet",300,"g"],["Chou-fleur",1,"pièce"],["Yaourt grec",1,"pot"],["Riz basmati",150,"g"],["Curry"]],"e":"Rôtir le chou-fleur en fleurettes avec le curry 25 min à 200 °C.\nCuire le riz et le poulet en dés.\nNapper de yaourt au curry."},{"n":"Steak de bœuf, champignons poêlés et patate douce","p":2,"t":35,"g":["viande","healthy"],"i":[["Steaks de bœuf",2,"pièce"],["Champignons",250,"g"],["Patates douces",2,"pièce"]],"e":"Rôtir les patates douces en cubes 25 min.\nPoêler les champignons 8 min.\nCuire les steaks selon la cuisson voulue."}]$j$::jsonb d),
foyer as (select id from foyers order by cree_le limit 1),
src as (select e from data, jsonb_array_elements(d) e),
ins as (
  insert into recettes (foyer_id, nom, portions, temps_min, etapes, tags, source)
  select foyer.id, e->>'n', (e->>'p')::int, (e->>'t')::int, e->>'e', array(select jsonb_array_elements_text(e->'g')), 'claude'
  from src, foyer where not exists (select 1 from recettes r where r.foyer_id = foyer.id and r.nom = e->>'n')
  returning id, nom
)
insert into recette_ingredients (recette_id, nom, quantite, unite, ordre)
select ins.id, i.v->>0, (i.v->>1)::numeric, i.v->>2, i.n - 1
from ins join src on src.e->>'n' = ins.nom
cross join lateral jsonb_array_elements(src.e->'i') with ordinality as i(v, n);
